const Ctx = createContext<{ lang: Lang; setLang: (l: Lang) => void }>({ lang: "is", setLang: () => {} });

export function LangProvider({ children }: { children: React.ReactNode }) {
  const [lang, setLangState] = useState<Lang>("is");
  useEffect(() => {
    // Default is "is" (matches SSR); only switch if the saved choice differs.
    const saved = localStorage.getItem("vakto-lang");
    if (saved === "en" || saved === "vi") {
      const id = requestAnimationFrame(() => setLangState(saved));
      return () => cancelAnimationFrame(id);
    }
  }, []);
  function setLang(l: Lang) {
    setLangState(l);
    try { localStorage.setItem("vakto-lang", l); } catch {}
  }
  return <Ctx.Provider value={{ lang, setLang }}>{children}</Ctx.Provider>;
}

export function useLang() {
  const { lang, setLang } = useContext(Ctx);
  // Fallback chain: vi → en → is(key) so partial translations still work.
  const t = (key: string) => {
    const e = DICT[key];
    if (!e) return key;
    if (lang === "vi") return e.vi ?? e.en ?? key;
    return e[lang] ?? key;
  };
  return { lang, setLang, t };
}
